insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$isa$tk$, 'ar', 24, $tk$عيسى$tk$, $tk$عيسى$tk$, $tk$المسيح ابن مريم$tk$, $tk$عيسى عليه السلام من أعظم رسل الله. والقرآن يسمِّيه المسيح ابن مريم، ويجعل لأمه مكانة فريدة: فسورة كاملة تحمل اسمها.

كانت مريم فتاة طاهرة عابدة. وذات يوم، وقد اعتزلت أهلها لتتعبد، تمثَّل لها ملَك وبشَّرها بأنها ستُرزق غلامًا زكيًّا. فتعجَّبت: كيف يكون لها ولد ولم يمسسها رجل؟ فأجابها الملَك بأن ذلك هيِّن على الله، الذي يخلق ما يشاء. فإذا قضى أمرًا فإنما يقول له: كن، فيكون.

وولدت مريم وحدها، عند جذع نخلة، في ألم وكرب. ثم جاءها ما يواسيها: جدول ماء يجري تحتها، ورُطَب طري يتساقط من النخلة إذا هزَّتها.

ولما رجعت إلى قومها تحمل الطفل، اتهموها. فاكتفت بأن أشارت إليه. فتكلَّم المولود حينئذ، بإذن الله. وقال إنه عبد الله، وإن الله آتاه الكتاب وجعله نبيًّا، وجعله مباركًا أينما كان، وأوصاه بالصلاة والزكاة وببرِّ والدته.

وأُرسل عيسى رسولًا إلى بني إسرائيل. فصدَّق التوراة التي جاءت قبله وأُوتي الإنجيل. وأيَّده الله بآيات بيِّنات: فبإذن الله، أبرأ الأعمى والأبرص، وأحيا الموتى، وصوَّر من الطين هيئة طير فصار طيرًا حيًّا. والقرآن يكرر في كل مرة أن هذه المعجزات وقعت بإذن الله.

وكانت رسالته هي رسالة الأنبياء جميعًا: الله ربي وربكم فاعبدوه، وذلك هو الصراط المستقيم. وآمن به الحواريون وأعلنوا أنهم مسلمون لله. وبطلب منهم، دعا عيسى ربه أن ينزل مائدة من السماء لتكون آية.

ويذكر القرآن أيضًا أن عيسى بشَّر برسول يأتي من بعده. ولما مكر به أعداؤه، يعلِّمنا القرآن أنهم ما قتلوه وما صلبوه، وإن شُبِّه لهم ذلك، وأن الله رفعه إليه.

والمسلمون يحبون عيسى وأمه ويكرمونهما.$tk$, $tk$برَّ أمك، واثبت على الحق برفق. فالعظمة الحقيقية أن تكون عبدًا وفيًّا لله، وأن تحمل الخير حيثما كنت.$tk$, $tk$["3:45-51","19:16-36","5:110-115","4:157-158","61:6"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.prophets (slug, lang, ord, name, name_ar, title, story, lesson, refs) values ($tk$muhammad$tk$, 'ar', 25, $tk$محمد ﷺ$tk$, $tk$محمد$tk$, $tk$خاتم النبيين، رحمة للعالمين$tk$, $tk$وُلد النبي محمد ﷺ في مكة نحو سنة 570م، في قبيلة قريش. وتوفي أبوه قبل مولده، وتوفيت أمه وهو طفل صغير، فكفله جده، ثم عمه أبو طالب. وفي شبابه، بلغ من صدقه وأمانته أن الناس كانوا يلقِّبونه بالأمين. وتزوج خديجة رضي الله عنها، وكانت تاجرة ذات مكانة في مكة.

وكان يخلو في غار حراء، في جبل قرب مكة، يتفكَّر ويتعبَّد. وهناك، وهو في نحو الأربعين من عمره، جاءه الملَك جبريل بأول ما نزل من القرآن، يأمره أن يقرأ باسم ربه الذي خلق. وكانت خديجة أول من آمن به.

وظل ثلاث عشرة سنة يدعو أهل مكة إلى عبادة الله وحده، وإلى الصدق، ورعاية الأيتام والفقراء، وترك الأصنام. فتبعه قليل من الناس، لكن سادة قريش عارضوه، ولقي المؤمنون السبَّ والمقاطعة والاضطهاد. فقابل ذلك بالصبر.

وفي سنة 622م، هاجر إلى مدينة يثرب، التي صارت المدينة. وهذه الرحلة، الهجرة، هي بداية التقويم الإسلامي. ويذكِّر القرآن بأنه، وهو مختبئ في غار مع صاحبه أبي بكر، قال له ألا يحزن، فإن الله معهما.

وفي المدينة بنى مسجدًا، وآخى بين المهاجرين القادمين من مكة وأهل المدينة، ونظَّم حياة الجماعة. واضطر المسلمون إلى الدفاع عن أنفسهم عدة مرات، وعقد النبي ﷺ كذلك هدنة مع قريش. فلما نُقضت، عاد إلى مكة في السنة 8 للهجرة، من غير قتال تقريبًا. وعفا عمن حاربوه سنين، وأزال الأصنام من الكعبة. ودخل الناس حينئذ في دين الله أفواجًا.

وفي السنة 10، حجَّ حجة الوداع. وفي عرفات خطب في جمع عظيم: فذكَّرهم بحرمة الدماء والأموال والأعراض، وأوصى بالإحسان إلى النساء، وأعلن أن ثارات الدماء القديمة والربا قد أُبطلت. وفي هذه الحجة نزلت الآية التي تعلن أن الدين قد أُكمل.

وتوفي في المدينة في السنة 11 للهجرة، الموافقة 632م. والقرآن يسمِّيه رسول الله وخاتم النبيين، أُرسل رحمة للعالمين.$tk$, $tk$كن أمينًا قبل أن تتحدث عن الإيمان: فالأخلاق تفتح القلوب. وإذا كانت لك الغلبة، فاختر الرحمة والعفو.$tk$, $tk$["96:1-5","9:40","110:1-3","5:3","33:40","21:107"]$tk$::jsonb)
  on conflict (slug, lang) do update set ord = excluded.ord, name = excluded.name, name_ar = excluded.name_ar, title = excluded.title, story = excluded.story, lesson = excluded.lesson, refs = excluded.refs;
insert into public.premium_content (kind, lang, payload) values ('hajj', 'ar', $tk${"umrah":{"title":"العمرة خطوة بخطوة","intro":"العمرة هي زيارة البيت الحرام في مكة. ويمكن أداؤها في أي وقت من السنة تقريبًا، ولا تستغرق إلا ساعات قليلة. وهي أربعة أعمال، تؤدَّى دائمًا بالترتيب نفسه: الإحرام من الميقات، والطواف حول الكعبة، والسعي بين الصفا والمروة، ثم الحلق أو التقصير.\n\nهذا الدليل خلاصة موجزة. وهو لا يغني عن معلِّم مؤهَّل، ولا عن تعليمات الجهات المسؤولة في المكان، وهي تعليمات ينبغي أن تتبعها دائمًا. وحيث تختلف المذاهب الفقهية في تفصيل ما، نذكر ما عليه عمل أكثر الناس: فاسأل عالِمًا تثق به عن حالتك.","chapters":[{"id":"preparation","title":"قبل السفر","body":"الرحلة الطيبة تبدأ من البيت. ابدأ بنيَّتك: أنت تسافر لله وحده، لا ليراك الناس أو يمدحوك. تُب توبة صادقة، وسدِّد ديونك قدر استطاعتك، واطلب السماح ممن قد تكون ظلمتهم. وأنفِق على رحلتك من مال حلال.\n\nثم تعلَّم المناسك قبل أن تذهب. فالحاج الذي يعرف ما عليه أن يفعله يكون مطمئنًّا، ويستطيع أن يُقبل بقلبه على العبادة بدل أن ينشغل بالقلق. اقرأ هذا الدليل عدة مرات، واحضر إن أمكن درسًا عند معلِّم.\n\nوأخيرًا، هيِّئ جسمك وأوراقك: امشِ بانتظام في الأسابيع السابقة، وتحقق من تأشيرتك وتصريحك ولقاحاتك، وخفِّف أمتعتك. فستمشي كثيرًا، وغالبًا في الحر والزحام.","steps":["أخلِص نيَّتك: هذه الرحلة لله وحده.","تُب، وسدِّد ديونك، واطلب السماح ممن حولك.","تعلَّم أعمال العمرة الأربعة وترتيبها.","تحقق من جواز سفرك وتأشيرتك وتصريحك واللقاحات المطلوبة.","اعرف أي ميقات يقع على طريقك ومتى ستبلغه.","تدرَّب على المشي، وخذ معك أشياء خفيفة مريحة."],"duas":[]},{"id":"miqat-ihram","title":"الميقات والإحرام","body":"الميقات هو الحد الذي لا يجوز للحاج أو المعتمر أن يتجاوزه إلا وهو مُحرِم. والمواقيت خمسة: ذو الحليفة للقادمين من المدينة، والجحفة، وقرن المنازل، ويلملم، وذات عرق. وفي الطائرة يعلن الطاقم في العادة عن الميقات: فكن مستعدًّا قبل تلك اللحظة.\n\nويُستحب الاغتسال (الغُسل) قبل الإحرام. يلبس الرجال قطعتين غير مخيطتين من القماش، إزارًا حول الوسط ورداء على الكتفين، وتلبس النساء ثيابهن المعتادة المحتشمة. ثم انوِ بقلبك وقل التلبية. يرفع الرجال صوتهم بها، وتخفض النساء أصواتهن.\n\nوالإحرام هو الحال التي يدخل فيها المرء، لا الثوب. وفيه لا يجوز لك أن تقصَّ شعرًا أو أظفارًا، ولا أن تتطيَّب، ولا أن تصيد، ولا أن تعقد نكاحًا، ولا أن تعاشر زوجك. ولا يلبس الرجال الثياب المفصَّلة على البدن ولا يغطون رؤوسهم، ولا تلبس النساء النقاب ولا القفازين (صحيح البخاري 1838). واجتنب الجدال كذلك (القرآن 2:197).","steps":["قبل الميقات، قلِّم أظفارك واغتسل إن استطعت.","الرجال: البسوا إزار الإحرام ورداءه. النساء: ابقين في ثيابكن المعتادة المحتشمة.","للرجال أن يطيِّبوا البدن، لا ثياب الإحرام، قبل النية، ولا يجوز ذلك بعدها أبدًا.","عند الميقات، انوِ العمرة بقلبك وقل: لبيك اللهم عمرة.","أكثِر من ترديد التلبية في الطريق إلى مكة.","من الآن فصاعدًا، التزم بترك كل ما يحظره الإحرام.","اقطع التلبية حين تبدأ الطواف."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"أجبتُ دعوتك يا الله مرة بعد مرة. أجبتُك، لا شريك لك، أجبتُك. الحمد كله والنعمة كلها لك، والمُلك كله لك. لا شريك لك.","source":"التلبية — صحيح البخاري 1549؛ صحيح مسلم 1184"}]},{"id":"tawaf","title":"الطواف حول الكعبة","body":"الطواف سبعة أشواط حول الكعبة، تجعلها فيها عن يسارك. ولا بد أن تكون على وضوء. وكل شوط يبدأ وينتهي عند الحجر الأسود: استقبله، وكبِّر، وقبِّله أو استلمه إن تيسَّر ذلك فقط، وإلا فاكتفِ بالإشارة إليه. وكثير من الحجاج يقولون عنده «بسم الله، الله أكبر»، كما رُوي عن الصحابي ابن عمر رضي الله عنهما. وطُف من خارج الجدار المقوَّس (الحِجر)، لا من داخله.\n\nوفي طواف القدوم هذا، يكشف الرجال الكتف الأيمن (الاضطباع)، ويسرعون المشي مع تقارب الخطى في الأشواط الثلاثة الأولى (الرَّمَل). أما النساء فيمشين مشيًا معتادًا.\n\nوليس لكل شوط دعاء محدد واجب: فلك أن تدعو بما شئت، بأي لغة، وأن تذكر الله أو تقرأ القرآن. ولم يُروَ دعاء معيَّن إلا بين الركن اليماني والحجر الأسود: وهو ما في القرآن 2:201. وبعد الطواف، صلِّ ركعتين خلف مقام إبراهيم (القرآن 2:125)، ثم اشرب من ماء زمزم.","steps":["تأكد من أنك على وضوء. يكشف الرجال الكتف الأيمن (الاضطباع).","ابدأ من محاذاة الحجر الأسود: استقبله، وكبِّر، وأشِر إليه إن لم تستطع الوصول إليه.","طُف سبعة أشواط والكعبة عن يسارك، مارًّا من خارج الحِجر.","يسرع الرجال المشي في الأشواط الثلاثة الأولى (الرَّمَل)، ثم يمشون مشيًا معتادًا.","استلم الركن اليماني إن تيسَّر، واقرأ بينه وبين الحجر الأسود ما في القرآن 2:201.","في أثناء الأشواط، ادعُ بما شئت.","بعد الشوط السابع، يغطي الرجال الكتف من جديد، ثم صلِّ ركعتين خلف مقام إبراهيم، أو في أي مكان من المسجد إن كان الزحام شديدًا.","اشرب من ماء زمزم وادعُ."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"الله أعظم من كل شيء.","source":"التكبير عند محاذاة الحجر الأسود — صحيح البخاري 1613"},{"ar":"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Rabbana atina fi ad-dunya hasanatan wa fi al-akhirati hasanatan wa qina 'adhab an-nar","t":"دعاء يسأل فيه العبد ربه أن يعطيه الخير في الدنيا والخير في الآخرة، وأن يحفظه من عذاب النار.","source":"القرآن 2:201 — يُقرأ بين الركن اليماني والحجر الأسود: سنن أبي داود 1892 (حسن)"}]},{"id":"say","title":"السعي بين الصفا والمروة","body":"بعد الطواف، اتجه إلى الصفا. والسعي سبعة أشواط بين الجبلين: من الصفا إلى المروة شوط، ومن المروة رجوعًا إلى الصفا الشوط الثاني، وهكذا. فتنتهي إذن عند المروة.\n\nوحين تقترب من الصفا أول مرة، اقرأ أول الآية 2:158 من القرآن، كما فعل النبي محمد ﷺ (صحيح مسلم 1218). اصعد قليلًا، واستقبل الكعبة، وارفع يديك، وكبِّر الله ووحِّده بالكلمات المذكورة أدناه، ثم ادعُ بما تريد. ويُفعل ذلك ثلاث مرات. وافعل مثله عند المروة كلما وصلت إليها.\n\nوبين العلمين الأخضرين يسرع الرجال في مشيهم، وتمشي النساء مشيًا معتادًا. وكما في الطواف، ليس لكل شوط دعاء معيَّن لازم. والوضوء مستحب، ولكبار السن والمرضى أن يستعملوا الكرسي المتحرك.","steps":["اتجه إلى الصفا، واقرأ أول الآية 2:158 من القرآن وأنت تقترب منه، في هذه المرة الأولى فقط.","على الصفا، استقبل الكعبة، وارفع يديك، وقل ذكر الصفا وادعُ، ثلاث مرات.","امشِ إلى المروة، ويسرع الرجال في مشيهم بين العلمين الأخضرين.","على المروة، استقبل الكعبة وأعِد الذكر والدعاء.","ارجع إلى الصفا: هذا هو الشوط الثاني.","استمر حتى الشوط السابع، وهو ينتهي عند المروة."],"duas":[{"ar":"إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِ","tr":"Inna as-Safa wa al-Marwata min sha'a'iri Allah","t":"الصفا والمروة من معالم دين الله التي جعلها مواضع لعبادته.","source":"القرآن 2:158 (أول الآية) — يُقرأ عند الاقتراب من الصفا: صحيح مسلم 1218"},{"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الأَحْزَابَ وَحْدَهُ","tr":"La ilaha illa Allahu wahdahu la sharika lah, lahu al-mulku wa lahu al-hamd, wa huwa 'ala kulli shay'in qadir. La ilaha illa Allahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazama al-ahzaba wahdah","t":"لا معبود بحق إلا الله وحده، لا شريك له. له المُلك وله الحمد، وهو قادر على كل شيء. لا معبود بحق إلا الله وحده، وفَّى بوعده، ونصر عبده، وهزم الأحزاب وحده.","source":"الذكر على الصفا والمروة — صحيح مسلم 1218"}]},{"id":"halq-taqsir","title":"الحلق أو التقصير","body":"آخر أعمال العمرة حلق الرأس (الحلق) أو تقصير الشعر (التقصير). والأفضل للرجال حلق الرأس كله، فإن قصَّروا، فالذي عليه عمل أكثر الناس تقصير شعر الرأس كله، لا بضع شعرات فقط. أما النساء فلا يحلقن أبدًا: بل يجمعن شعرهن ويقصصن من طرفه قدر أنملة.\n\nوالرجل الذي يعتمر قبل الحج بقليل (التمتع) يختار كثيرًا أن يقصِّر الآن، ليبقى له شعر يحلقه في اليوم العاشر.\n\nواقصد الحلاقين خارج المسجد بدل قصِّ الشعر في المسعى، وينبغي أن تقصَّ النساء شعرهن في مكان مستور. وبهذا العمل تتم العمرة، وتنتهي كل محظورات الإحرام.","steps":["اخرج من المسعى بعد انتهاء الشوط السابع.","الرجال: احلقوا الرأس، أو قصِّروا شعر الرأس كله.","النساء: اقصصن قدر أنملة من طرف الشعر، في مكان مستور.","لقد تحلَّلت الآن من الإحرام: تمَّت عمرتك."],"duas":[]},{"id":"after","title":"بعد العمرة","body":"انتهت عمرتك: فاشكر الله الذي بلَّغك بيته. وكل ما كان الإحرام قد حظره عاد مباحًا، ولك أن تلبس ثيابك المعتادة.\n\nوأحسِن استغلال أيامك الباقية في مكة. صلِّ الصلوات الخمس في المسجد الحرام ما استطعت، وطُف تطوعًا حين لا يكون الزحام شديدًا، واقرأ القرآن، وادعُ لنفسك ولأهلك ولجميع المسلمين. وكن رفيقًا بغيرك من الحجاج، صبورًا على التعب والزحام.\n\nوكثير من الحجاج يسافرون أيضًا إلى المدينة للصلاة في المسجد النبوي. وهذه الزيارة عمل مبارك في نفسه، لكنها ليست جزءًا من العمرة. وإذا رجعت إلى بلدك، فاجتهد في المحافظة على العادات الطيبة التي اكتسبتها هناك.","steps":["اشكر الله والبس ثيابك المعتادة من جديد.","صلِّ في المسجد الحرام ما استطعت.","طُف تطوعًا، واقرأ القرآن، وأكثِر من الدعاء.","حافظ على عادات الرحلة الطيبة بعد عودتك إلى بلدك."],"duas":[]}]},"hajj":{"title":"الحج يومًا بيوم","intro":"الحج هو الركن الخامس من أركان الإسلام. وهو واجب مرة في العمر على كل مسلم بالغ يستطيع السفر إليه (القرآن 3:97). وتؤدَّى مناسكه الرئيسية من اليوم 8 إلى اليوم 13 من ذي الحجة، بين مكة ومنى وعرفات ومزدلفة.\n\nوله ثلاث صفات. في التمتع، تؤدي عمرة كاملة في أشهر الحج، ثم تتحلَّل من الإحرام، ثم تُحرِم من جديد بالحج في اليوم 8. وفي القِران، تجمع بين العمرة والحج بإحرام واحد، من غير أن تتحلَّل بينهما. وفي الإفراد، تُحرِم بالحج وحده. ويجب الهدي في التمتع والقِران (القرآن 2:196)، ولا يجب في الإفراد. والثلاثة كلها صحيحة، والعلماء يختلفون في أيها أفضل، وأكثر الحجاج القادمين من بعيد يحجُّون متمتعين.\n\nهذا الدليل خلاصة موجزة. وهو لا يغني عن معلِّم مؤهَّل، ولا عن تعليمات الجهات المسؤولة في المكان وتعليمات حملتك، وهي التي تنظِّم التنقلات والمواعيد حفاظًا على سلامة الجميع. وحيث تختلف المذاهب الفقهية في تفصيل ما، نذكر ما عليه عمل أكثر الناس: فاسأل عالِمًا تثق به عن حالتك.","chapters":[{"id":"day-8-tarwiyah","title":"8 ذو الحجة: يوم التروية، في منى","body":"يبدأ الحج في اليوم 8 من ذي الحجة، ويسمى يوم التروية. فالحاج المتمتع يُحرِم من جديد، بالحج هذه المرة، من مكان إقامته في مكة: يغتسل، ويلبس ثياب الإحرام، وينوي، ثم يلبِّي. أما القارن والمفرِد فما زالا على إحرامهما منذ الميقات.\n\nثم يذهب الجميع إلى منى، وهي وادٍ من الخيام على بعد كيلومترات قليلة من مكة. وهناك تصلِّي الظهر والعصر والمغرب والعشاء ثم فجر اليوم 9، كل صلاة في وقتها، وتُقصر الصلوات الرباعية إلى ركعتين، من غير جمع.\n\nوهذا اليوم وهذه الليلة في منى سُنَّة ووقت استعداد. فاسترح، وردِّد التلبية، واقرأ القرآن، وهيِّئ قلبك للغد، أعظم أيام الحج.","steps":["المتمتع: اغتسل والبس الإحرام في مكان إقامتك في مكة.","انوِ الحج بقلبك وقل: لبيك اللهم حجًّا.","اذهب إلى منى مع حملتك، وأنت تردِّد التلبية.","صلِّ الظهر والعصر والمغرب والعشاء في منى، كل صلاة في وقتها، مع قصر الرباعية.","بِت في منى وصلِّ الفجر فيها."],"duas":[{"ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ","tr":"Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, inna al-hamda wa an-ni'mata laka wa al-mulk, la sharika lak","t":"أجبتُ دعوتك يا الله مرة بعد مرة. أجبتُك، لا شريك لك، أجبتُك. الحمد كله والنعمة كلها لك، والمُلك كله لك. لا شريك لك.","source":"التلبية — صحيح البخاري 1549؛ صحيح مسلم 1184"}]},{"id":"day-9-arafat","title":"9 ذو الحجة: عرفات، ثم مزدلفة","body":"الوقوف بعرفة هو ركن الحج: فمن فاته فقد فاته الحج. وقد علَّم النبي محمد ﷺ أن الحج عرفة (جامع الترمذي 889).\n\nبعد شروق الشمس، اخرج من منى إلى عرفات، وتأكد من أنك داخل حدودها، وهي مبيَّنة باللوحات. وبعد الخطبة، تُصلَّى الظهر والعصر جمعًا وقصرًا، في وقت الظهر. ثم يأتي قلب الحج: من الظهيرة إلى غروب الشمس، استقبل القبلة وادعُ الله، واستغفره، وادعُ لمن تحب. وليس هناك نص لازم. ولا تخرج قبل الغروب.\n\nوبعد الغروب، اذهب بسكينة إلى مزدلفة. وهناك تصلِّي المغرب والعشاء جمعًا، مع قصر العشاء، ثم تستريح الليل في العراء. ولك أن تلتقط منها الحصى الصغار للرمي.","steps":["بعد شروق الشمس، اذهب من منى إلى عرفات، وأنت تردِّد التلبية.","تأكد من أنك داخل حدود عرفات.","صلِّ الظهر والعصر جمعًا وقصرًا في وقت الظهر.","اقضِ ما بعد الظهر في الدعاء والذكر والتوبة، مستقبلًا القبلة.","ابقَ في عرفات حتى تغرب الشمس تمامًا.","اذهب بسكينة إلى مزدلفة وصلِّ فيها المغرب والعشاء جمعًا.","التقط حصى صغارًا، بحجم حبة الحمص، ثم نَم.","صلِّ الفجر، وادعُ مستقبلًا القبلة، وانطلق إلى منى قبل شروق الشمس."],"duas":[]},{"id":"day-10-nahr","title":"10 ذو الحجة: يوم النحر","body":"اليوم 10 هو يوم العيد وأكثر أيام الحج أعمالًا. وتؤدَّى فيه أربعة أعمال، والأفضل أن تكون بهذا الترتيب. أولًا، في منى، ارمِ سبع حصيات واحدة بعد واحدة على جمرة العقبة، وهي الجمرة الكبرى، مكبِّرًا مع كل حصاة، وهنا تنقطع التلبية (صحيح البخاري 1685). ثانيًا، الهدي، وهو واجب في التمتع والقِران، وكثيرًا ما يُرتَّب عن طريق قسيمة رسمية. ثالثًا، يحلق الرجال أو يقصِّرون، وتقصُّ النساء قدر أنملة. رابعًا، في مكة، طواف الإفاضة، وهو ركن من أركان الحج، ويتبعه سعي الحج لمن بقي عليه.\n\nوبعد الرمي والحلق، تُرفع محظورات الإحرام، إلا المعاشرة الزوجية، فإنها تحلُّ بعد طواف الإفاضة. والمذاهب تختلف في التفاصيل: فاسأل عالِمًا تثق به عن حالتك.\n\nوإن تغيَّر الترتيب فلا حرج: فقد قال النبي محمد ﷺ ذلك لمن سألوه في ذلك اليوم (صحيح البخاري 83).","steps":["في منى، ارمِ سبع حصيات واحدة بعد واحدة على جمرة العقبة، قائلًا: الله أكبر، مع كل حصاة.","اقطع التلبية حين تبدأ الرمي.","اذبح الهدي، أو تأكد من أنه ذُبح عنك (في التمتع والقِران).","يحلق الرجال الرأس كله أو يقصِّرون شعره كله، وتقصُّ النساء قدر أنملة.","البس ثيابك المعتادة: فقد عاد كل شيء مباحًا إلا المعاشرة الزوجية.","اذهب إلى مكة لطواف الإفاضة، بلا اضطباع ولا رَمَل، وصلِّ ركعتين.","اسعَ سعي الحج إن كان ما زال عليك.","ارجع إلى منى لتبيت فيها."],"duas":[{"ar":"اللَّهُ أَكْبَرُ","tr":"Allahu akbar","t":"الله أعظم من كل شيء.","source":"التكبير مع كل حصاة — صحيح البخاري 1751"}]},{"id":"days-11-13-tashriq","title":"11-13 ذو الحجة: أيام التشريق","body":"تُقضى أيام التشريق في منى. وهي أيام ذكر لله (القرآن 2:203)، ويُبات فيها بمنى كذلك.\n\nوفي كل يوم، بعد الزوال، ترمي الجمرات الثلاث بالترتيب: الصغرى، ثم الوسطى، ثم جمرة العقبة، كل واحدة بسبع حصيات، مكبِّرًا مع كل رمية. وبعد الأولى وبعد الثانية، تنحَّ جانبًا، واستقبل القبلة، وادعُ طويلًا رافعًا يديك، وبعد الثالثة انصرف من غير وقوف (صحيح البخاري 1751).\n\nولك أن تخرج من منى في اليوم 12 بعد الرمي، قبل غروب الشمس، ومن بقي رمى مرة أخرى في اليوم 13. وكلاهما جائز (القرآن 2:203). واتبع الجدول الزمني المعطى لحملتك. وإن كنت ضعيفًا أو مريضًا، أو كان سؤالك عن الوقت المحدد للرمي، فاسأل عالِمًا تثق به عن حالتك.","steps":["بِت ليلتَي 11 و12 في منى.","في كل يوم بعد الزوال، خذ 21 حصاة إلى الجمرات.","ارمِ الجمرة الصغرى بسبع حصيات، ثم تنحَّ جانبًا وادعُ.","ارمِ الجمرة الوسطى بسبع حصيات، ثم تنحَّ جانبًا وادعُ.","ارمِ جمرة العقبة بسبع حصيات وانصرف من غير وقوف.","في اليوم 12، اخرج من منى قبل غروب الشمس إن أردت التعجُّل.","وإلا فبِت فيها وارمِ الجمرات الثلاث مرة أخرى في اليوم 13."],"duas":[]},{"id":"farewell-tawaf","title":"طواف الوداع","body":"إذا انتهت المناسك كلها وأوشكت أن تغادر مكة، فآخر ما تفعله طواف الوداع. فقد أُمر الناس أن يكون آخر عهدهم بالبيت، ولم يُعفَ من ذلك إلا المرأة الحائض (صحيح البخاري 1755؛ صحيح مسلم 1328).\n\nوهو طواف عادي من سبعة أشواط بالثياب المعتادة، بلا اضطباع ولا رَمَل، تتبعه ركعتان. ولا سعي بعده. وأدِّه حين تكون أمتعتك جاهزة وسفرك قريبًا، ولا يضرُّ انتظار قصير لوسيلة النقل أو للرفقة.\n\nواخرج من المسجد الحرام بقلب شاكر. واسأل الله أن يتقبل حجك، وأن يغفر لك، وأن يكتب لك العودة. ثم اجتهد أن ترجع إلى بلدك إنسانًا أفضل من الذي خرج منه.","steps":["أتمَّ كل مناسكك وجهِّز أمتعتك أولًا.","طُف سبعة أشواط حول الكعبة بالثياب المعتادة.","صلِّ ركعتين بعد الطواف.","ادعُ الله أن يتقبل حجك، ثم غادر مكة من غير تأخير.","المرأة الحائض تغادر من غير هذا الطواف."],"duas":[]}]},"mistakes":[{"title":"المزاحمة لتقبيل الحجر الأسود","body":"تقبيل الحجر الأسود سُنَّة، وإيذاء المسلم حرام. فإن اشتد الزحام، فاكتفِ بالإشارة إلى الحجر وكبِّر: طوافك تام، ولم يتأذَّ أحد."},{"title":"اعتقاد أن لكل شوط دعاء خاصًّا لازمًا","body":"بعض الكتيِّبات تذكر دعاء لكل شوط. ولا يلزم شيء من ذلك: فليس لأشواط الطواف ولا لأشواط السعي دعاء محدد واجب. خاطِب الله بكلماتك أنت، وبلغتك أنت."},{"title":"الخروج من عرفات قبل الغروب","body":"بقي النبي محمد ﷺ في عرفات حتى غربت الشمس (صحيح مسلم 1218). فلا تتعجَّل إلى الحافلات في آخر العصر: فهذه أثمن ساعات الحج كله."},{"title":"صعود جبل الرحمة ظنًّا أنه لازم","body":"صعيد عرفات كله موقف. وصعود الجبل ليس من الحج ولا يزيد في الأجر، والتدافع هناك متعب وخطير. فابقَ حيث تستطيع أن تدعو في طمأنينة."},{"title":"الوقوف خارج حدود عرفات","body":"بعض الحجاج ينزلون خارج عرفات بقليل وهم لا يشعرون. ولأن الوقوف هو ركن الحج، فابحث عن لوحات الحدود، واسأل مرشدك إن كان عندك أدنى شك."},{"title":"التقاط حصى أكبر مما ينبغي","body":"الحصى صغار، بحجم حبة الحمص تقريبًا. أما الحجارة الكبيرة والأحذية وغيرها من الأشياء فليست من النُّسُك، وقد تصيب الناس بالأذى. والرمي طاعة لله تؤدَّى بسكينة، لا انفجار غضب."},{"title":"التصوير بدل العبادة","body":"صورة للذكرى تأخذ ثواني قليلة، أما تصوير الطواف كله أو البث المباشر من عرفات فيصرف قلبك عن العبادة. فضع الهاتف جانبًا في أثناء المناسك، واحفظ إخلاص نيَّتك."},{"title":"إهمال الميقات عند السفر بالطائرة","body":"تعبر الطائرة الميقات في الجو. فالبس ثياب الإحرام قبل الصعود إلى الطائرة أو في أول الرحلة، وانوِ حين يُعلن عن الميقات، أو قبله بقليل. وإن تجاوزته غير مُحرِم، فاسأل عالِمًا تثق به عن حالتك."},{"title":"إبقاء الكتف الأيمن مكشوفًا طوال الوقت","body":"الاضطباع خاص بالرجال، وفي طواف القدوم وحده. وقبله وبعده، ومن ذلك وقت الصلاة والسعي، يُغطَّى الكتفان كلاهما."},{"title":"عدُّ الذهاب والرجوع شوطًا واحدًا في السعي","body":"من الصفا إلى المروة شوط، ومن المروة إلى الصفا شوط آخر. والسعي سبعة أشواط وينتهي عند المروة. وعدُّ كل ذهاب ورجوع شوطًا واحدًا معناه أن تمشي أربعة عشر شوطًا."},{"title":"الإصرار على الصلاة خلف مقام إبراهيم مباشرة","body":"الصلاة في طريق الطائفين تعطِّلهم وتعرِّضك للخطر. فإذا اشتد الزحام، جاز أن تُصلَّى الركعتان في أي مكان من المسجد."},{"title":"الجدال وفقدان الصبر","body":"الحر والطوابير والتعب امتحان للجميع. والقرآن ينهى عن الرفث والفسوق والجدال في الحج (2:197). فأفسِح لغيرك، وابتسم، واعفُ: فحسن الخلق جزء من حجك."}],"checklist":[{"id":"passport","group":"documents","label":"جواز سفر صالح لستة أشهر على الأقل"},{"id":"visa-permit","group":"documents","label":"تأشيرة الحج أو العمرة والتصريح الرسمي"},{"id":"tickets-bookings","group":"documents","label":"تذاكر الطيران وحجوزات السكن"},{"id":"id-copies","group":"documents","label":"نسخ ورقية ورقمية من جميع الوثائق"},{"id":"emergency-contacts","group":"documents","label":"بطاقة فيها أرقام حملتك وفندقك وأرقام الطوارئ"},{"id":"money-card","group":"documents","label":"شيء من النقود المحلية وبطاقة مصرفية"},{"id":"ihram-garments","group":"clothing","label":"الرجال: طقمان من ثياب الإحرام"},{"id":"modest-clothing","group":"clothing","label":"النساء: ثياب واسعة محتشمة مريحة"},{"id":"sandals","group":"clothing","label":"نعال مريحة سبق لك لبسها"},{"id":"ihram-belt","group":"clothing","label":"حزام الإحرام أو كيس للنقود والأوراق"},{"id":"small-bag","group":"clothing","label":"كيس صغير للحذاء والحصى"},{"id":"umbrella","group":"clothing","label":"مظلة فاتحة اللون تقي من الشمس"},{"id":"vaccinations","group":"health","label":"اللقاحات المطلوبة وشهادتها"},{"id":"medication","group":"health","label":"أدويتك المعتادة مع الوصفة الطبية"},{"id":"unscented-toiletries","group":"health","label":"صابون وأدوات نظافة غير معطَّرة للإحرام"},{"id":"water-bottle","group":"health","label":"قارورة ماء قابلة لإعادة الاستعمال"},{"id":"masks-sanitizer","group":"health","label":"كمامات ومعقِّم يدين غير معطَّر"},{"id":"first-aid","group":"health","label":"حقيبة إسعافات أولية صغيرة فيها لصقات لتقرُّحات القدم"},{"id":"sincere-intention","group":"spiritual","label":"جدِّد نيَّتك: لله وحده"},{"id":"repentance-debts","group":"spiritual","label":"تُب، وسدِّد الديون، واطلب السماح"},{"id":"learn-rites","group":"spiritual","label":"تعلَّم المناسك وترتيبها"},{"id":"talbiyah-memorised","group":"spiritual","label":"احفظ التلبية"},{"id":"dua-list","group":"spiritual","label":"اكتب قائمة بأدعيتك الخاصة ليوم عرفات"},{"id":"quran-dhikr","group":"spiritual","label":"مصحف جيب أو تطبيق للقراءة والذكر"}]}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('quiz', 'ar', $tk$[{"id":"q001","cat":"prophets","q":"بحسب القرآن الكريم، من هو أول إنسان خلقه الله؟","options":["نوح","آدم","إبراهيم","إدريس"],"answer":1,"explain":"آدم عليه السلام هو أول إنسان وأبو البشر. ويذكر القرآن خلقه في 2:30-37."},{"id":"q002","cat":"prophets","q":"أي نبي عليه السلام صنع السفينة بأمر الله؟","options":["موسى","يونس","نوح","هود"],"answer":2,"explain":"أُمر نوح عليه السلام بصنع السفينة قبل الطوفان، كما جاء في القرآن (11:37)."},{"id":"q003","cat":"prophets","q":"أي نبي عليه السلام ابتلعه حوت عظيم؟","options":["أيوب","يوسف","إلياس","يونس"],"answer":3,"explain":"ابتلع الحوت يونس عليه السلام، فدعا الله في الظلمات فنجَّاه (37:139-144)."},{"id":"q004","cat":"prophets","q":"أي الأبناء أعان إبراهيم عليه السلام على رفع قواعد الكعبة؟","options":["إسحاق","يعقوب","إسماعيل","لوط"],"answer":2,"explain":"يذكر القرآن أن إبراهيم وإسماعيل عليهما السلام رفعا قواعد البيت معًا (2:127)."},{"id":"q005","cat":"prophets","q":"أي نبي عليه السلام ألقاه إخوته في البئر وهو صغير؟","options":["يحيى","يوسف","هارون","داود"],"answer":1,"explain":"ألقى يوسفَ عليه السلام في البئر إخوتُه الذين حسدوه. وقصته تملأ سورة يوسف، وهي السورة 12 (12:15)."},{"id":"q006","cat":"prophets","q":"على أي نبي عليه السلام أُنزلت التوراة؟","options":["عيسى","داود","إبراهيم","موسى"],"answer":3,"explain":"أُوتي التوراةَ موسى عليه السلام، الذي خرج ببني إسرائيل من مصر."},{"id":"q007","cat":"prophets","q":"أي نبي عليه السلام أُوتي الزبور؟","options":["داود","سليمان","موسى","زكريا"],"answer":0,"explain":"يذكر القرآن أن الله آتى داود عليه السلام الزبور (4:163 و17:55)."},{"id":"q008","cat":"prophets","q":"أي نبي عليه السلام أُوتي الإنجيل؟","options":["عيسى","يحيى","موسى","يونس"],"answer":0,"explain":"أُوتي الإنجيلَ عيسى ابن مريم عليهما السلام، كما جاء في القرآن في 5:46."},{"id":"q009","cat":"prophets","q":"أي نبي كان أخا موسى عليه السلام وأعانه في رسالته؟","options":["يوشع","شعيب","إلياس","هارون"],"answer":3,"explain":"سأل موسى ربه أن يجعل أخاه هارون معينًا له (20:29-32). عليهما السلام."},{"id":"q010","cat":"prophets","q":"أي نبي عليه السلام، ابتُلي ببلاء طويل، اشتهر بصبره وبدعائه ربه بأنه «أرحم الراحمين»؟","options":["أيوب","هارون","لوط","صالح"],"answer":0,"explain":"صبر أيوب عليه السلام على بلائه ودعا ربه، فكشف عنه ما به (21:83-84)."},{"id":"q011","cat":"prophets","q":"أي نبي عليه السلام أُرسل إلى قوم عاد؟","options":["صالح","شعيب","هود","لوط"],"answer":2,"explain":"أُرسل هود عليه السلام إلى قوم عاد يدعوهم إلى عبادة الله وحده (7:65)."},{"id":"q012","cat":"prophets","q":"الناقة التي جُعلت آية لقوم ثمود مرتبطة بأي نبي عليه السلام؟","options":["هود","صالح","نوح","يونس"],"answer":1,"explain":"أُرسل صالح عليه السلام إلى ثمود، وكانت الناقة آية لهم من الله (7:73)."},{"id":"q013","cat":"prophets","q":"أي نبي عليه السلام ألقاه قومه في النار فجعلها الله بردًا وسلامًا عليه؟","options":["موسى","إبراهيم","يحيى","هود"],"answer":1,"explain":"لما ألقى القوم إبراهيم عليه السلام في النار، أمرها الله أن تكون بردًا وسلامًا عليه (21:68-69)."},{"id":"q014","cat":"prophets","q":"بحسب القرآن الكريم، أي نبي عليه السلام فهم كلام نملة تحذِّر سائر النمل؟","options":["يونس","عيسى","سليمان","يوسف"],"answer":2,"explain":"سمع سليمان عليه السلام نملة تحذِّر النمل حين اقترب جيشه، فتبسَّم وشكر الله (27:18-19)."},{"id":"q015","cat":"prophets","q":"أي نبي عليه السلام كان والد يحيى؟","options":["عمران","يعقوب","أيوب","زكريا"],"answer":3,"explain":"دعا زكريا عليه السلام ربه أن يرزقه ولدًا وهو شيخ كبير، فبُشِّر بيحيى (19:7)."},{"id":"q016","cat":"seerah","q":"في أي مدينة وُلد النبي محمد ﷺ؟","options":["المدينة المنورة","مكة المكرمة","الطائف","القدس"],"answer":1,"explain":"وُلد النبي محمد ﷺ في مكة، في قبيلة قريش."},{"id":"q017","cat":"seerah","q":"أين نزل الوحي أول مرة على النبي محمد ﷺ؟","options":["في غار ثور","في غار حراء","على جبل أُحد","في صعيد عرفات"],"answer":1,"explain":"نزل الوحي أول مرة في غار حراء، في جبل النور قرب مكة، حيث كان يخلو بنفسه."},{"id":"q018","cat":"seerah","q":"أي ملَك نزل بالوحي على النبي محمد ﷺ؟","options":["ميكائيل","جبريل","إسرافيل","مالك"],"answer":1,"explain":"نزل الملَك جبريل عليه السلام بالقرآن على النبي محمد ﷺ."},{"id":"q019","cat":"seerah","q":"ما أول كلمة من القرآن نزلت على النبي محمد ﷺ؟","options":["قُل","قُم","اقرأ","سبِّح"],"answer":2,"explain":"يبدأ أول ما نزل من الوحي بكلمة «اقرأ»، وهي أمر بالقراءة والتلاوة (96:1)."},{"id":"q020","cat":"seerah","q":"من هي أولى زوجات النبي محمد ﷺ؟","options":["خديجة بنت خويلد","عائشة بنت أبي بكر","حفصة بنت عمر","سودة بنت زمعة"],"answer":0,"explain":"خديجة رضي الله عنها، وكانت تاجرة ذات مكانة في مكة، هي أولى زوجاته. ولم يتزوج عليها امرأة أخرى في حياتها."},{"id":"q021","cat":"seerah","q":"في أي سنة ميلادية كانت الهجرة من مكة إلى المدينة؟","options":["622","570","610","632"],"answer":0,"explain":"كانت الهجرة سنة 622م. وصارت تلك السنة لاحقًا السنة الأولى في التقويم الهجري."},{"id":"q022","cat":"seerah","q":"ماذا كانت المدينة المنورة تسمى قبل الهجرة؟","options":["خيبر","تبوك","الطائف","يثرب"],"answer":3,"explain":"كانت تسمى يثرب. وبعد أن استقر فيها النبي محمد ﷺ عُرفت باسم «المدينة»."},{"id":"q023","cat":"seerah","q":"في أي غار اختبأ النبي محمد ﷺ في أثناء الهجرة؟","options":["غار ثور","غار حراء","غار في جبل أُحد","غار في جبل الصفا"],"answer":0,"explain":"اختبأ في غار ثور مع صاحبه أبي بكر رضي الله عنه وقريش تبحث عنهما. ويذكر القرآن هذا الموقف في 9:40."},{"id":"q024","cat":"seerah","q":"في أي سنة من الهجرة وقعت غزوة بدر؟","options":["السنة الثانية","السنة الأولى","السنة الخامسة","السنة الثامنة"],"answer":0,"explain":"وقعت غزوة بدر في رمضان من السنة الثانية للهجرة. وكانت أول معركة كبرى للمسلمين."},{"id":"q025","cat":"seerah","q":"ما اسم الجد الذي كفل النبي محمدًا ﷺ بعد وفاة أمه؟","options":["أبو لهب","أبو سفيان","عبد المطلب","ورقة بن نوفل"],"answer":2,"explain":"كفله جده عبد المطلب، وكان من سادة مكة. وبعد وفاة الجد ضمَّه إليه عمه أبو طالب."},{"id":"q026","cat":"seerah","q":"ما اسم أم النبي محمد ﷺ؟","options":["حليمة السعدية","فاطمة بنت أسد","أم أيمن","آمنة بنت وهب"],"answer":3,"explain":"أمه هي آمنة بنت وهب. وقد توفيت وهو ما زال طفلًا صغيرًا. أما حليمة السعدية فكانت مرضعته."},{"id":"q027","cat":"seerah","q":"إلى أي قبيلة ينتمي النبي محمد ﷺ؟","options":["الأوس","الخزرج","ثقيف","قريش"],"answer":3,"explain":"كان من قريش، قبيلة مكة، من بني هاشم."},{"id":"q028","cat":"seerah","q":"ما اسم الهدنة التي عُقدت بين المسلمين وقريش في السنة السادسة للهجرة؟","options":["بيعة العقبة","صحيفة المدينة","صلح الحديبية","حلف الفضول"],"answer":2,"explain":"عُقد صلح الحديبية في السنة السادسة للهجرة قرب مكة. وجاءت بعده فترة سلام انتشر فيها الإسلام انتشارًا واسعًا."},{"id":"q029","cat":"seerah","q":"في أي سنة من الهجرة كان فتح مكة؟","options":["السنة الثانية","السنة الرابعة","السنة الثامنة","السنة السادسة"],"answer":2,"explain":"دخل المسلمون مكة في السنة الثامنة للهجرة (630م). وعفا النبي محمد ﷺ عن أهلها."},{"id":"q030","cat":"seerah","q":"قبل النبوة، بأي لقب كان أهل مكة يلقِّبون النبي محمدًا ﷺ؟","options":["الحكيم","الكريم","الشجاع","الأمين"],"answer":3,"explain":"كان يُعرف بالأمين لصدقه وأمانته. وكان الناس يودعون عنده نفائسهم."},{"id":"q031","cat":"companions","q":"من هو أول مؤذن في الإسلام؟","options":["سلمان الفارسي","أنس بن مالك","بلال بن رباح","زيد بن حارثة"],"answer":2,"explain":"بلال بن رباح رضي الله عنه، وهو عبد مُعتَق من أصل حبشي، اختاره النبي محمد ﷺ ليرفع الأذان."},{"id":"q032","cat":"companions","q":"أي صحابي رافق النبي محمدًا ﷺ في الهجرة؟","options":["بلال بن رباح","مصعب بن عمير","خالد بن الوليد","أبو بكر الصديق"],"answer":3,"explain":"كان أبو بكر رضي الله عنه صاحبه في الرحلة من مكة إلى المدينة، وكان معه في غار ثور."},{"id":"q033","cat":"companions","q":"أي صحابي أشار بحفر خندق للدفاع عن المدينة؟","options":["بلال بن رباح","أبو أيوب الأنصاري","سلمان الفارسي","مصعب بن عمير"],"answer":2,"explain":"سلمان الفارسي رضي الله عنه، القادم من بلاد فارس، هو الذي أشار بالخندق. ولذلك تسمى غزوة السنة الخامسة للهجرة غزوة الخندق."},{"id":"q034","cat":"companions","q":"أي صحابي يُعرف بلقب «سيف الله»؟","options":["خالد بن الوليد","بلال بن رباح","زيد بن ثابت","أنس بن مالك"],"answer":0,"explain":"خالد بن الوليد رضي الله عنه، القائد المشهور، يُعرف بسيف الله."},{"id":"q035","cat":"companions","q":"من هو أول من آمن برسالة النبي محمد ﷺ؟","options":["عمر بن الخطاب","خديجة بنت خويلد","خالد بن الوليد","أبو سفيان"],"answer":1,"explain":"كانت زوجته خديجة رضي الله عنها أول من آمن به. وقد واسته وآزرته منذ أول نزول الوحي."},{"id":"q036","cat":"companions","q":"في عهد أي خليفة اعتُمد التقويم الهجري، وجُعلت سنة الهجرة بدايته؟","options":["عمر بن الخطاب","هارون الرشيد","عبد الملك بن مروان","عمر بن عبد العزيز"],"answer":0,"explain":"وُضع التقويم الهجري في خلافة عمر بن الخطاب رضي الله عنه، بعد وفاة النبي محمد ﷺ ببضع سنين."},{"id":"q037","cat":"companions","q":"أي صحابي من كُتَّاب الوحي كُلِّف بجمع القرآن في مجموع واحد مكتوب؟","options":["بلال بن رباح","خالد بن الوليد","سلمان الفارسي","زيد بن ثابت"],"answer":3,"explain":"زيد بن ثابت رضي الله عنه، أحد كُتَّاب النبي محمد ﷺ، جمع القرآن المكتوب في مجموع واحد في خلافة أبي بكر رضي الله عنه."},{"id":"q038","cat":"companions","q":"أي صحابي أُرسل إلى يثرب قبل الهجرة ليعلِّم أهلها الإسلام؟","options":["مصعب بن عمير","خالد بن الوليد","أنس بن مالك","أبو أيوب الأنصاري"],"answer":0,"explain":"أُرسل مصعب بن عمير رضي الله عنه إلى يثرب بعد بيعة العقبة الأولى. وأسلم على يديه كثير من أهلها."},{"id":"q039","cat":"companions","q":"في أي غزوة استُشهد حمزة، عم النبي محمد ﷺ؟","options":["بدر","الخندق","حنين","أُحد"],"answer":3,"explain":"استُشهد حمزة بن عبد المطلب رضي الله عنه في غزوة أُحد، في السنة الثالثة للهجرة."},{"id":"q040","cat":"companions","q":"من يُذكر على أنه أول شهيد في الإسلام؟","options":["أم أيمن","سمية بنت خياط","حليمة السعدية","أم سلمة"],"answer":1,"explain":"سمية بنت خياط رضي الله عنها، أم عمار بن ياسر، قُتلت في مكة لأنها أبت أن تترك دينها."},{"id":"q041","cat":"companions","q":"أي صحابي تكلَّم باسم المهاجرين المسلمين أمام النجاشي ملك الحبشة؟","options":["بلال بن رباح","جعفر بن أبي طالب","زيد بن ثابت","أنس بن مالك"],"answer":1,"explain":"شرح جعفر بن أبي طالب رضي الله عنه الإسلام للنجاشي، فترك المسلمين يعيشون آمنين في بلاده."},{"id":"q042","cat":"companions","q":"أي بنات النبي محمد ﷺ تزوجت علي بن أبي طالب؟","options":["فاطمة","زينب","رقية","أم كلثوم"],"answer":0,"explain":"تزوجت فاطمة عليَّ بن أبي طالب في المدينة، رضي الله عنهما. وهما والدا الحسن والحسين."},{"id":"q043","cat":"companions","q":"بأي اسم يُعرف أهل المدينة الذين استقبلوا المهاجرين القادمين من مكة ونصروهم؟","options":["المهاجرون","قريش","التابعون","الأنصار"],"answer":3,"explain":"يسمى مسلمو المدينة الأنصار. أما الذين هاجروا من مكة فيسمَّون المهاجرين."},{"id":"q044","cat":"companions","q":"من نام في فراش النبي محمد ﷺ ليلة خروجه من مكة مهاجرًا؟","options":["زيد بن حارثة","بلال بن رباح","علي بن أبي طالب","أنس بن مالك"],"answer":2,"explain":"نام الفتى علي بن أبي طالب رضي الله عنه مكانه في الفراش تلك الليلة، وبقي بعده ليردَّ الأمانات التي كان الناس قد أودعوها عنده."},{"id":"q045","cat":"companions","q":"في بيت من أقام النبي محمد ﷺ في المدينة ريثما يُبنى مسجده؟","options":["سلمان الفارسي","أبو أيوب الأنصاري","خالد بن الوليد","مصعب بن عمير"],"answer":1,"explain":"نزل في بيت أبي أيوب الأنصاري رضي الله عنه حتى بُني مسجده وحُجُراته."},{"id":"q046","cat":"quran","q":"كم عدد سور القرآن الكريم؟","options":["114","99","110","120"],"answer":0,"explain":"في القرآن 114 سورة، من الفاتحة إلى الناس."},{"id":"q047","cat":"quran","q":"ما أطول سورة في القرآن؟","options":["آل عمران","النساء","يس","البقرة"],"answer":3,"explain":"البقرة، وهي السورة 2، أطول سور القرآن."},{"id":"q048","cat":"quran","q":"ما أقصر سورة في القرآن؟","options":["الإخلاص","الكوثر","الفلق","الفاتحة"],"answer":1,"explain":"الكوثر، وهي السورة 108، أقصر السور: فليس فيها إلا ثلاث آيات قصار."},{"id":"q049","cat":"quran","q":"بأي سورة يُفتتح القرآن؟","options":["البقرة","الإخلاص","الفاتحة","العلق"],"answer":2,"explain":"الفاتحة هي أول سور القرآن، وتُقرأ في كل صلاة."},{"id":"q050","cat":"quran","q":"ما السورة التي تأتي آخرًا في المصحف؟","options":["الفلق","الإخلاص","الناس","النصر"],"answer":2,"explain":"الناس، وهي السورة 114، تختم القرآن."},{"id":"q051","cat":"quran","q":"إلى كم جزء يُقسم القرآن؟","options":["7","30","60","114"],"answer":1,"explain":"يُقسم القرآن إلى 30 جزءًا، وهذا ييسِّر قراءته كله في شهر واحد."},{"id":"q052","cat":"quran","q":"في أي شهر بدأ نزول القرآن؟","options":["رمضان","رجب","المحرَّم","ذو الحجة"],"answer":0,"explain":"يذكر القرآن أنه أُنزل في شهر رمضان (2:185)."},{"id":"q053","cat":"quran","q":"في أي سورة توجد آية الكرسي؟","options":["آل عمران","البقرة","الكهف","الملك"],"answer":1,"explain":"آية الكرسي هي الآية 255 من سورة البقرة (2:255)."},{"id":"q054","cat":"quran","q":"ما السورة الوحيدة التي لا تبدأ بالبسملة؟","options":["التوبة","الأنفال","يونس","الملك"],"answer":0,"explain":"التوبة، وهي السورة 9، هي السورة الوحيدة التي لا تُفتتح بالبسملة، أي «بسم الله الرحمن الرحيم»."},{"id":"q055","cat":"quran","q":"في أي سورة ترد البسملة مرتين؟","options":["النحل","العنكبوت","سبأ","النمل"],"answer":3,"explain":"في سورة النمل ترد البسملة في أولها، ثم ترد مرة أخرى في كتاب سليمان عليه السلام (27:30)."},{"id":"q056","cat":"quran","q":"أي سورة من القرآن تحمل اسم أم عيسى عليه السلام؟","options":["النساء","مريم","آل عمران","النور"],"answer":1,"explain":"السورة 19 سُمِّيت باسم مريم، أم عيسى عليهما السلام. وهي المرأة الوحيدة المذكورة باسمها في القرآن."},{"id":"q057","cat":"quran","q":"في كم سنة تقريبًا نزل القرآن؟","options":["نحو 23 سنة","نحو 3 سنوات","نحو 10 سنوات","نحو 40 سنة"],"answer":0,"explain":"نزل القرآن شيئًا فشيئًا في نحو 23 سنة، في مكة أولًا ثم في المدينة."},{"id":"q058","cat":"quran","q":"كم عدد آيات سورة الفاتحة؟","options":["3","5","10","7"],"answer":3,"explain":"في الفاتحة سبع آيات. وتُقرأ في كل ركعة من الصلاة."},{"id":"q059","cat":"quran","q":"ماذا تسمى السور التي نزلت قبل الهجرة؟","options":["المدنية","المحكَم","المكية","المفصَّل"],"answer":2,"explain":"السور التي نزلت قبل الهجرة تسمى مكية، والتي نزلت بعدها تسمى مدنية."},{"id":"q060","cat":"quran","q":"ما أطول آية في القرآن؟","options":["آية الكرسي (2:255)","آية النور (24:35)","آية الدَّين (2:282)","الآية الأولى من الفاتحة"],"answer":2,"explain":"أطول آية هي الآية 282 من سورة البقرة. وهي تعلِّم الناس أن يكتبوا ديونهم وأن يُشهدوا عليها."},{"id":"q061","cat":"history","q":"أي مدينة كانت عاصمة الخلافة الأموية؟","options":["بغداد","دمشق","القاهرة","المدينة المنورة"],"answer":1,"explain":"حكم الأمويون من دمشق، في الشام، من سنة 661م إلى سنة 750م."},{"id":"q062","cat":"history","q":"أي خليفة عباسي أسس مدينة بغداد سنة 762م؟","options":["هارون الرشيد","المنصور","المأمون","المعتصم"],"answer":1,"explain":"أسس الخليفة المنصور بغداد سنة 762م على ضفاف دجلة. وصارت من أعظم مدن العالم."},{"id":"q063","cat":"history","q":"من استولى على بغداد ودمَّرها سنة 1258م؟","options":["المغول","الصليبيون","السلاجقة","العثمانيون"],"answer":0,"explain":"استولى جيش المغول بقيادة هولاكو على بغداد سنة 1258م، وبذلك انتهت الخلافة العباسية في بغداد."},{"id":"q064","cat":"history","q":"أي سلطان عثماني فتح القسطنطينية سنة 1453م؟","options":["محمد الثاني","سليمان القانوني","سليم الأول","عثمان الأول"],"answer":0,"explain":"محمد الثاني، المعروف بالفاتح، فتح القسطنطينية سنة 1453م. وصارت المدينة عاصمة العثمانيين، إسطنبول."},{"id":"q065","cat":"history","q":"من قاد الجيش الإسلامي الذي عبر من شمال إفريقيا إلى شبه الجزيرة الإيبيرية سنة 711م؟","options":["عقبة بن نافع","خالد بن الوليد","صلاح الدين الأيوبي","طارق بن زياد"],"answer":3,"explain":"عبر طارق بن زياد المضيق سنة 711م. والصخرة المعروفة بجبل طارق تحمل اسمه."},{"id":"q066","cat":"history","q":"من استردَّ القدس من الصليبيين سنة 1187م؟","options":["بيبرس","نور الدين زنكي","صلاح الدين الأيوبي","محمد الثاني"],"answer":2,"explain":"استردَّ صلاح الدين الأيوبي القدس سنة 1187م، بعد انتصاره في معركة حطين."},{"id":"q067","cat":"history","q":"أي مدينة، وهي آخر مملكة إسلامية في الأندلس، سقطت سنة 1492م؟","options":["قرطبة","غرناطة","إشبيلية","طليطلة"],"answer":1,"explain":"سقطت مملكة غرناطة، مملكة بني نصر، سنة 1492م، وانتهت بذلك نحو ثمانية قرون من الحكم الإسلامي في أجزاء من شبه الجزيرة الإيبيرية."},{"id":"q068","cat":"history","q":"من هزم المغول في معركة عين جالوت سنة 1260م؟","options":["مماليك مصر","العثمانيون","السلاجقة","الموحِّدون"],"answer":0,"explain":"أوقف مماليك مصر زحف المغول في عين جالوت، في فلسطين، سنة 1260م."},{"id":"q069","cat":"history","q":"أي دولة تولَّت الخلافة سنة 750م ثم اتخذت بغداد عاصمة لها؟","options":["العثمانيون","المماليك","المرابطون","العباسيون"],"answer":3,"explain":"خلف العباسيون الأمويين سنة 750م، وأسسوا بغداد سنة 762م."},{"id":"q070","cat":"history","q":"أي أمير أموي فرَّ إلى الأندلس وأسس إمارة قرطبة سنة 756م؟","options":["طارق بن زياد","هارون الرشيد","صلاح الدين الأيوبي","عبد الرحمن الداخل"],"answer":3,"explain":"عبد الرحمن الأول، المعروف بالداخل، وهو من الناجين من البيت الأموي، بلغ الأندلس وأسس إمارة قرطبة سنة 756م."},{"id":"q071","cat":"history","q":"تأخذ الدولة العثمانية اسمها من مؤسسها. فمن هو؟","options":["محمد الثاني","تيمورلنك","ألب أرسلان","عثمان الأول"],"answer":3,"explain":"أسس عثمان الأول الدولة العثمانية في الأناضول نحو سنة 1300م. ومن اسمه جاءت تسمية «العثمانيين»."},{"id":"q072","cat":"history","q":"من أسس الدولة المغولية في الهند سنة 1526م؟","options":["أكبر","شاه جهان","بابر","أورنكزيب"],"answer":2,"explain":"أسس بابر الدولة المغولية في الهند بعد انتصاره في معركة باني بت سنة 1526م."},{"id":"q073","cat":"history","q":"أي سلطان عثماني من القرن السادس عشر الميلادي يُعرف بلقبَي «العظيم» و«القانوني»؟","options":["محمد الثاني","سليمان الأول","عثمان الأول","عبد الحميد الثاني"],"answer":1,"explain":"حكم سليمان الأول من سنة 1520م إلى سنة 1566م، حين كانت الدولة العثمانية في أوج قوتها. ويلقَّب بالقانوني، أي واضع القوانين."},{"id":"q074","cat":"history","q":"منسا موسى، المشهور بحجِّه إلى مكة سنة 1324م، حكم أي إمبراطورية؟","options":["إمبراطورية سونغاي","إمبراطورية غانا","إمبراطورية مالي","إمبراطورية كانم"],"answer":2,"explain":"حكم منسا موسى إمبراطورية مالي في غرب إفريقيا. وقد جعل حجُّه سنة 1324م ثراء مالي مشهورًا في الآفاق."},{"id":"q075","cat":"history","q":"أي سلطان سلجوقي انتصر على البيزنطيين في معركة ملاذكرد سنة 1071م؟","options":["صلاح الدين الأيوبي","بيبرس","ألب أرسلان","عثمان الأول"],"answer":2,"explain":"هزم ألب أرسلان الجيش البيزنطي في ملاذكرد سنة 1071م، ففُتحت أبواب الأناضول أمام الأتراك."},{"id":"q076","cat":"sciences","q":"أي فرع من الرياضيات أخذ اسمه في لغات العالم من عنوان كتاب للخوارزمي؟","options":["الهندسة","الجبر","حساب المثلثات","الحساب"],"answer":1,"explain":"اسم علم الجبر في اللغات الأخرى مأخوذ من كلمة «الجبر» الواردة في عنوان الكتاب الذي ألَّفه الخوارزمي في بغداد في القرن التاسع الميلادي."},{"id":"q077","cat":"sciences","q":"كلمة «ألغوريتم» المستعملة في اللغات الأوروبية مأخوذة من الصيغة اللاتينية لاسم أي عالِم؟","options":["الخوارزمي","الكندي","البيروني","البتَّاني"],"answer":0,"explain":"كلمة «ألغوريتم» مأخوذة من «ألغوريتمي»، وهي الصيغة اللاتينية لاسم الرياضي الخوارزمي."},{"id":"q078","cat":"sciences","q":"من مؤلف كتاب «القانون في الطب»؟","options":["الرازي","الزهراوي","ابن سينا","ابن النفيس"],"answer":2,"explain":"ألَّف ابن سينا القانون في الطب في القرن الحادي عشر الميلادي. وظل يُستعمل في تعليم الطب قرونًا، في العالم الإسلامي وفي أوروبا."},{"id":"q079","cat":"sciences","q":"أي عالِم ألَّف «كتاب المناظر» وبيَّن أننا نرى لأن الضوء يدخل العين؟","options":["الخوارزمي","ابن الهيثم","ابن خلدون","الإدريسي"],"answer":1,"explain":"ابن الهيثم، الذي عاش في القرنين العاشر والحادي عشر الميلاديين، ألَّف كتاب المناظر واعتمد على تجارب دقيقة."},{"id":"q080","cat":"sciences","q":"العالِم الأندلسي الزهراوي مشهور بأنه رائد في أي مجال؟","options":["علم الفلك","الجراحة","الجغرافيا","الجبر"],"answer":1,"explain":"الزهراوي، الذي عاش قرب قرطبة في القرن العاشر الميلادي، وصف العمليات الجراحية وآلات كثيرة في موسوعته «التصريف»."},{"id":"q081","cat":"sciences","q":"أي طبيب ألَّف رسالة مشهورة فرَّقت بين الجدري والحصبة؟","options":["الكندي","الفارابي","الإدريسي","الرازي"],"answer":3,"explain":"الرازي، وهو طبيب كبير من القرنين التاسع والعاشر الميلاديين، ألَّف رسالة في الجدري والحصبة تصف المرضين وصفًا دقيقًا."},{"id":"q082","cat":"sciences","q":"أي طبيب من القرن الثالث عشر الميلادي وصف كيف يمرُّ الدم من القلب عبر الرئتين؟","options":["الخوارزمي","البيروني","ابن النفيس","ابن خلدون"],"answer":2,"explain":"وصف ابن النفيس الدورة الدموية الرئوية في القرن الثالث عشر الميلادي، قبل أن تُعرف في أوروبا بزمن طويل."},{"id":"q083","cat":"sciences","q":"أي عالِم من القرن الحادي عشر الميلادي حسب نصف قطر الأرض وألَّف دراسة كبرى عن الهند؟","options":["ابن رشد","جابر بن حيان","الزهراوي","البيروني"],"answer":3,"explain":"حسب البيروني نصف قطر الأرض بطريقة بارعة، وكانت نتيجته قريبة من القيمة الحديثة، وألَّف كتابًا مفصَّلًا عن الهند."},{"id":"q084","cat":"sciences","q":"أي جغرافي رسم خريطة مشهورة للعالم للملك روجر الثاني ملك صقلية في القرن الثاني عشر الميلادي؟","options":["ابن بطوطة","ابن خلدون","الإدريسي","الخوارزمي"],"answer":2,"explain":"أتمَّ الإدريسي خريطته للعالم والكتاب المصاحب لها سنة 1154م، في بلاط روجر الثاني في صقلية."},{"id":"q085","cat":"sciences","q":"جابر بن حيان معروف خصوصًا بأعماله في أي مجال؟","options":["البصريات","الجراحة","الكيمياء","الجغرافيا"],"answer":2,"explain":"جابر بن حيان من كبار أعلام الكيمياء القديمة (الخيمياء)، وتُنسب إليه مؤلفات كثيرة."},{"id":"q086","cat":"sciences","q":"في أي مدينة كان بيت الحكمة، المكتبة العباسية الشهيرة المرتبطة بحركة الترجمة؟","options":["بغداد","قرطبة","القاهرة","دمشق"],"answer":0,"explain":"كان بيت الحكمة في بغداد العباسية، حيث كان العلماء يترجمون ويدرسون مؤلفات من التراث اليوناني والفارسي والهندي."},{"id":"q087","cat":"sciences","q":"من مؤلف «المقدمة»، الكتاب المشهور في التاريخ والمجتمع؟","options":["ابن خلدون","ابن بطوطة","ابن رشد","الغزالي"],"answer":0,"explain":"ابن خلدون، المولود في تونس سنة 1332م، هو مؤلف المقدمة. ويُعدُّ رائدًا سبق إلى علم الاجتماع وإلى الدراسة الحديثة للتاريخ."},{"id":"q088","cat":"sciences","q":"فيمَ كان يُستعمل الأسطرلاب، وهو آلة أتقنها العلماء المسلمون؟","options":["قياس درجة الحرارة","وزن الذهب والفضة","طحن الحبوب","رصد مواقع الشمس والنجوم"],"answer":3,"explain":"كان الأسطرلاب يُستعمل لرصد الشمس والنجوم، وهذا يعين الناس على معرفة الوقت وتحديد الاتجاهات."},{"id":"q089","cat":"sciences","q":"بماذا يُعرف المهندس الجزري، الذي أتمَّ كتابه المشهور سنة 1206م؟","options":["آلات بديعة وساعات مائية","خريطة للعالم","رسالة في الجدري","كتاب في الجبر"],"answer":0,"explain":"ألَّف الجزري كتاب «الجامع بين العلم والعمل النافع في صناعة الحيل»، وفيه وصف لساعات مائية ومضخات وآلات ذاتية الحركة."},{"id":"q090","cat":"sciences","q":"بأي اسم لاتيني يُعرف العالِم الأندلسي ابن رشد في أوروبا؟","options":["أفيسينا (Avicenna)","الهازن (Alhazen)","رازيس (Rhazes)","أفيرويس (Averroes)"],"answer":3,"explain":"ابن رشد القرطبي يُعرف باسم أفيرويس. وقد انتشرت قراءة شروحه على أرسطو في أوروبا في العصور الوسطى."},{"id":"q091","cat":"pillars","q":"كم عدد أركان الإسلام؟","options":["ثلاثة","خمسة","أربعة","سبعة"],"answer":1,"explain":"أركان الإسلام خمسة: الشهادتان، والصلاة، والزكاة، وصوم رمضان، والحج إلى مكة."},{"id":"q092","cat":"pillars","q":"ما الركن الأول من أركان الإسلام؟","options":["الصلاة","الصوم","الحج","الشهادتان"],"answer":3,"explain":"الركن الأول هو الشهادتان: أن تشهد أن لا إله إلا الله وأن محمدًا ﷺ رسول الله."},{"id":"q093","cat":"pillars","q":"كم عدد الصلوات المفروضة في اليوم؟","options":["اثنتان","ثلاث","خمس","سبع"],"answer":2,"explain":"الصلوات المفروضة في اليوم خمس: الفجر والظهر والعصر والمغرب والعشاء."},{"id":"q094","cat":"pillars","q":"ما اسم صلاة أول النهار التي تُصلَّى عند طلوع الفجر؟","options":["الظهر","الفجر","العصر","العشاء"],"answer":1,"explain":"الفجر هي صلاة طلوع الفجر، وهي أولى الصلوات الخمس اليومية."},{"id":"q095","cat":"pillars","q":"كم عدد الركعات المفروضة في صلاة الفجر؟","options":["ركعة واحدة","ركعتان","ثلاث ركعات","أربع ركعات"],"answer":1,"explain":"صلاة الفجر المفروضة ركعتان."},{"id":"q096","cat":"pillars","q":"ما ترتيب شهر رمضان بين شهور التقويم الهجري؟","options":["التاسع","الأول","السابع","الثاني عشر"],"answer":0,"explain":"رمضان هو الشهر التاسع في التقويم الهجري. وهو شهر الصيام."},{"id":"q097","cat":"pillars","q":"في رمضان، متى يبدأ صيام كل يوم؟","options":["عند طلوع الفجر","عند شروق الشمس","عند الظهر","عند منتصف الليل"],"answer":0,"explain":"يبدأ الصيام عند طلوع الفجر، حين يظهر أول الضوء، كما يبيِّن القرآن في 2:187."},{"id":"q098","cat":"pillars","q":"ماذا تسمى الوجبة التي يُنهى بها الصيام في المساء؟","options":["السحور","الوليمة","العقيقة","الإفطار"],"answer":3,"explain":"الإفطار هو الوجبة التي يُنهى بها الصيام. أما السحور فهو الوجبة التي تؤكل قبل الفجر."},{"id":"q099","cat":"pillars","q":"ما المقدار المعتاد لزكاة المدَّخرات كالنقود والذهب والفضة؟","options":["2.5%","1%","5%","15%"],"answer":0,"explain":"زكاة المدَّخرات 2.5%، أي ربع العُشر، إذا بقي النصاب في مِلك صاحبه سنة قمرية كاملة."},{"id":"q100","cat":"pillars","q":"في أي شهر يكون الحج؟","options":["رمضان","ذو الحجة","المحرَّم","شوال"],"answer":1,"explain":"يكون الحج في ذي الحجة، وهو الشهر الثاني عشر والأخير في التقويم الهجري."},{"id":"q101","cat":"pillars","q":"كم مرة يدور الحجاج حول الكعبة في الطواف الواحد؟","options":["ثلاث مرات","خمس مرات","سبع مرات","تسع مرات"],"answer":2,"explain":"الطواف سبعة أشواط حول الكعبة."},{"id":"q102","cat":"pillars","q":"بين أي جبلين يمشي الحجاج في السعي؟","options":["أُحد وثور","عرفات ومنى","الصفا والمروة","حراء وثور"],"answer":2,"explain":"يمشي الحجاج سبع مرات بين الصفا والمروة، وقد وصفهما القرآن بأنهما من شعائر الله (2:158)."},{"id":"q103","cat":"pillars","q":"في أي يوم من ذي الحجة يقف الحجاج بعرفة؟","options":["اليوم التاسع","اليوم الأول","اليوم العاشر","اليوم الثالث عشر"],"answer":0,"explain":"الوقوف بعرفة يكون في اليوم التاسع من ذي الحجة. وهو قلب الحج."},{"id":"q104","cat":"pillars","q":"كم مرة في العمر يجب الحج على المسلم المستطيع؟","options":["ثلاث مرات","كل سنة","كل خمس سنوات","مرة واحدة"],"answer":3,"explain":"يجب الحج مرة واحدة في العمر على من استطاع السفر إليه (3:97)."},{"id":"q105","cat":"pillars","q":"إلى أي مدينة كان المسلمون الأوائل يتجهون في صلاتهم قبل أن تصير الكعبة هي القبلة؟","options":["المدينة المنورة","دمشق","الطائف","القدس"],"answer":3,"explain":"كان المسلمون الأوائل يصلُّون نحو بيت المقدس. ثم حُوِّلت القبلة إلى المسجد الحرام في مكة (2:144)."},{"id":"q106","cat":"civilisation","q":"من أسس جامع القرويين في فاس في القرن التاسع الميلادي، وهو الذي صار جامعة مشهورة؟","options":["رابعة العدوية","فاطمة الفهرية","زبيدة بنت جعفر","شجر الدر"],"answer":1,"explain":"بحسب الروايات، أسست فاطمة الفهرية جامع القرويين في فاس، في المغرب، سنة 859م. ويوصف كثيرًا بأنه أقدم جامعة ما زالت تعمل."},{"id":"q107","cat":"civilisation","q":"في أي مدينة من مدن الأندلس يقع الجامع الكبير المشهور بغابة أعمدته وأقواسه الحمراء والبيضاء؟","options":["إشبيلية","قرطبة","غرناطة","طليطلة"],"answer":1,"explain":"بدأ بناء جامع قرطبة الكبير في القرن الثامن الميلادي، حين كانت قرطبة عاصمة الأندلس."},{"id":"q108","cat":"civilisation","q":"في أي مدينة يقع قصر الحمراء؟","options":["غرناطة","قرطبة","مراكش","فاس"],"answer":0,"explain":"يقع قصر الحمراء في غرناطة، في جنوب إسبانيا. وكان قصر حكام بني نصر."},{"id":"q109","cat":"civilisation","q":"أي إمبراطور مغولي أمر ببناء تاج محل؟","options":["أكبر","بابر","أورنكزيب","شاه جهان"],"answer":3,"explain":"أمر شاه جهان ببناء تاج محل في أغرا في القرن السابع عشر الميلادي، تخليدًا لذكرى زوجته ممتاز محل."},{"id":"q110","cat":"civilisation","q":"في أي مدينة وُلد الرحالة الكبير ابن بطوطة؟","options":["فاس","تونس","القاهرة","طنجة"],"answer":3,"explain":"وُلد ابن بطوطة في طنجة، في المغرب، سنة 1304م. وظل يرتحل نحو ثلاثين سنة في إفريقيا وآسيا وأوروبا."},{"id":"q111","cat":"civilisation","q":"تمبكتو، المركز المشهور للعلم والمخطوطات، تقع في أي بلد من بلدان اليوم؟","options":["مصر","المغرب","مالي","السودان"],"answer":2,"explain":"تقع تمبكتو في مالي. وكانت مساجدها ومدارسها تجتذب الطلاب والعلماء من أنحاء غرب إفريقيا."},{"id":"q112","cat":"civilisation","q":"في أي مدينة يقع الأزهر، وهو من أقدم جامعات العالم؟","options":["بغداد","القاهرة","دمشق","القيروان"],"answer":1,"explain":"تأسس الأزهر في القاهرة في القرن العاشر الميلادي، وما زال إلى اليوم مركزًا كبيرًا للعلم."},{"id":"q113","cat":"civilisation","q":"في أي مدينة تقع قبة الصخرة؟","options":["القدس","دمشق","المدينة المنورة","القاهرة"],"answer":0,"explain":"تقع قبة الصخرة في القدس. وقد اكتمل بناؤها في أواخر القرن السابع الميلادي في عهد الخليفة الأموي عبد الملك."},{"id":"q114","cat":"civilisation","q":"أي معماري عثماني صمَّم جامع السليمانية في إسطنبول؟","options":["الجزري","أولوغ بيك","المعمار سنان","ابن خلدون"],"answer":2,"explain":"المعمار سنان، كبير معماريي الدولة العثمانية في القرن السادس عشر الميلادي، صمَّم السليمانية في إسطنبول والسليمية في أدرنة."},{"id":"q115","cat":"civilisation","q":"في العالم الإسلامي في العصور الوسطى، ما «البيمارستان»؟","options":["مكتبة","مرصد فلكي","سوق مسقوفة","مستشفى"],"answer":3,"explain":"البيمارستان هو المستشفى. وكان في مدن مثل بغداد ودمشق والقاهرة مستشفيات كبيرة يُعالج فيها المرضى."},{"id":"q116","cat":"civilisation","q":"ما أول شهور التقويم الهجري؟","options":["المحرَّم","رمضان","رجب","شوال"],"answer":0,"explain":"المحرَّم هو أول الشهور الاثني عشر في التقويم الهجري، وهو تقويم يتبع القمر."},{"id":"q117","cat":"civilisation","q":"ما المحراب في المسجد؟","options":["المنبر الذي تُلقى منه خطبة الجمعة","التجويف الذي يدل على اتجاه مكة","البرج الذي يُرفع منه الأذان","النافورة التي يُتوضأ منها"],"answer":1,"explain":"المحراب تجويف في الجدار يدل على القبلة، أي اتجاه مكة. أما المنصة التي يخطب عليها الإمام فتسمى المنبر، وأما البرج فيسمى المئذنة."},{"id":"q118","cat":"civilisation","q":"جامع القيروان الكبير، وهو من أقدم جوامع إفريقيا، يقع في أي بلد؟","options":["تونس","المغرب","مصر","سوريا"],"answer":0,"explain":"تقع القيروان في تونس. ويعود جامعها الكبير إلى تأسيس المدينة على يد عقبة بن نافع سنة 670م."},{"id":"q119","cat":"civilisation","q":"الخط الكوفي، وهو من أقدم أنواع الخط العربي، يُنسب إلى أي مدينة؟","options":["قرطبة","قونية","الكوفة","كابل"],"answer":2,"explain":"يأخذ الخط الكوفي اسمه من الكوفة، في العراق. وقد كُتب كثير من المصاحف الأولى بهذا الخط ذي الزوايا."},{"id":"q120","cat":"civilisation","q":"ما «الوقف» في الحضارة الإسلامية؟","options":["قافلة تجارية","نوع من الخط","مال محبوس على أعمال الخير","ضريبة على المحاصيل"],"answer":2,"explain":"الوقف مال يُحبس على وجوه الخير، كمدرسة أو مستشفى أو سبيل ماء. ويظل ريعه ينفع الناس على مرِّ الزمن."}]$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
insert into public.premium_content (kind, lang, payload) values ('days', 'ar', $tk${"new-year":{"detail":"أول يوم من شهر المحرم هو بداية السنة الهجرية. والتقويم الإسلامي تقويم قمري: يبدأ كل شهر فيه بظهور الهلال الجديد، ولذلك فإن السنة الهجرية أقصر من السنة الشمسية بنحو أحد عشر يومًا.\n\nوقد وُضع هذا التقويم في عهد الخليفة عمر بن الخطاب، بعد سنوات من وفاة النبي محمد ﷺ. واختار الصحابة أن يبدأ عدّ السنين من الهجرة، أي انتقال النبي ﷺ من مكة إلى المدينة سنة 622 للميلاد، وأن يبقى المحرم أول شهور السنة. أما الهجرة نفسها فقد وقعت بعد ذلك في السنة نفسها، في شهر ربيع الأول.\n\nوالمحرم أحد الأشهر الحرم الأربعة المذكورة في القرآن (9:36). وقد علّم النبي ﷺ أن أفضل الصيام بعد رمضان هو صيام شهر الله المحرم (صحيح مسلم 1163).\n\nولم تُشرع لهذا اليوم صلاة خاصة ولا احتفال خاص. وكثير من المسلمين يغتنمونه لتذكّر الهجرة، ومراجعة ما مضى من عامهم، وتجديد العزم على الخير.","sources":["القرآن 9:36","صحيح مسلم 1163"]},"tasua":{"detail":"تاسوعاء هو اليوم التاسع من شهر المحرم، وهو اليوم الذي يسبق عاشوراء.\n\nلما صام النبي محمد ﷺ يوم عاشوراء وأمر المسلمين بصيامه، ذكر له أصحابه أن اليهود والنصارى يعظّمون هذا اليوم أيضًا. فأجاب بأنهم في العام المقبل، إن شاء الله، سيصومون اليوم التاسع كذلك. وقد توفي ﷺ قبل أن يأتي المحرم التالي (صحيح مسلم 1134).\n\nولهذا يستحب العلماء صيام اليوم التاسع مع اليوم العاشر. وبذلك يكون لصيام المسلمين صورته الخاصة، مع بقاء الصلة باليوم الذي نجّى الله فيه موسى عليه السلام.\n\nوهذا الصيام تطوع وليس واجبًا. فمن لم يستطع إلا صيام اليوم العاشر فقد صام عاشوراء، ولا ينبغي لمن كان مريضًا أو مسافرًا أو عاجزًا عن الصيام أن يشعر بالذنب. وشهر المحرم كله شهر حرام، وقد علّم النبي ﷺ أن الصيام فيه أفضل الصيام بعد رمضان (صحيح مسلم 1163).","sources":["صحيح مسلم 1134","صحيح مسلم 1163"]},"ashura":{"detail":"عاشوراء هو اليوم العاشر من شهر المحرم. وترجع قصته إلى نبي الله موسى عليه السلام: ففي مثل هذا اليوم نجّاه الله هو وبني إسرائيل من عدوّهم.\n\nولما قدم النبي محمد ﷺ المدينة وجد اليهود يصومون هذا اليوم إحياءً لذكرى تلك النجاة. فقال إن المسلمين أحقّ بموسى من غيرهم، فصام هذا اليوم وأمر المسلمين بأن يصوموه (صحيح البخاري 2004). ولما فُرض صيام شهر رمضان بعد ذلك، بقي صيام يوم عاشوراء عملًا من أعمال التطوع المستحبة (صحيح البخاري 2002).\n\nوسُئل النبي ﷺ عن ثواب صيامه فقال إنه يكفّر ذنوب السنة التي مضت (صحيح مسلم 1162). ويُستحب لمن أراد صيام عاشوراء أن يصوم معه أيضًا اليوم التاسع من شهر المحرم، أي اليوم الذي قبله (صحيح مسلم 1134).","sources":["صحيح البخاري 2004","صحيح البخاري 2002","صحيح مسلم 1162","صحيح مسلم 1134"]},"mawlid":{"detail":"وُلد النبي محمد ﷺ في مكة، في بني هاشم من قبيلة قريش، في العام المعروف بعام الفيل، نحو سنة 570 للميلاد. وقد توفي أبوه عبد الله قبل ولادته، وتوفيت أمه آمنة وهو طفل صغير.\n\nومن الثابت أنه وُلد يوم الاثنين: فقد سُئل عن صيام يوم الاثنين فقال إنه اليوم الذي وُلد فيه واليوم الذي نزل عليه فيه الوحي (صحيح مسلم 1162). وأكثر المؤرخين على أن ولادته كانت في شهر ربيع الأول. واليوم الثاني عشر هو أشهر التواريخ، لكن ذُكرت أيام أخرى، وليس في شيء منها يقين.\n\nويختلف المسلمون في إحياء هذا اليوم. فكثير منهم يجتمعون لتذكّر سيرته والصلاة عليه وتقاسم الطعام. وآخرون لا يخصّون هذا اليوم بشيء، لأن النبي ﷺ وأصحابه لم يفعلوا ذلك. والجميع متفقون على محبته واتباع هديه في كل يوم، وقد وصفه القرآن بأنه رحمة للعالمين (21:107).","sources":["صحيح مسلم 1162","القرآن 21:107"]},"isra-miraj":{"detail":"الإسراء هو رحلة النبي محمد ﷺ ليلًا من المسجد الحرام في مكة إلى المسجد الأقصى في بيت المقدس. وقد ذكره القرآن في أول سورة الإسراء (17:1). والمعراج هو صعوده من هناك إلى السماوات، حيث لقي أنبياء سابقين عليهم السلام وأُري آيات عظيمة من آيات ربه، وقد أشارت سورة النجم إلى ذلك (53:13-18).\n\nوقع ذلك في مكة قبل الهجرة، في فترة شدة مرّ بها النبي ﷺ. وأبقى عطايا تلك الليلة أثرًا الصلوات الخمس اليومية، فقد فُرضت حينئذ (صحيح البخاري 349).\n\nوالتاريخ الدقيق غير معروف على وجه اليقين. وليلة السابع والعشرين من رجب هي أشهر ما يُذكر، لكن المؤرخين الأوائل ذكروا تواريخ أخرى.\n\nولم تثبت لهذه الليلة صلاة خاصة ولا صيام خاص. وكثير من المسلمين يغتنمون المناسبة لرواية الحدث وتذكّر قيمة الصلاة، وآخرون لا يحيون هذا التاريخ. ورجب أحد الأشهر الحرم الأربعة (9:36).","sources":["القرآن 17:1","القرآن 53:13-18","صحيح البخاري 349","القرآن 9:36"]},"mid-shaban":{"detail":"شعبان هو الشهر الثامن، ويأتي قبل رمضان مباشرة. وقد روت عائشة رضي الله عنها أنها لم ترَ النبي محمدًا ﷺ يصوم في شهر، غير رمضان، أكثر مما كان يصوم في شعبان (صحيح البخاري 1969). فهو شهر استعداد: صيام تطوع، وقضاء ما فات من صيام رمضان الماضي، وقراءة القرآن.\n\nوليلة الخامس عشر، في منتصف الشهر، تُعرف في بلدان كثيرة بأسماء مثل ليلة البراءة أو شبِ برات أو نصف شعبان. وقد وردت عدة روايات تذكر مغفرة الله في هذه الليلة. واختلف العلماء في قوة هذه الروايات، ولذلك اختلفوا في العمل: فكثير من المسلمين يقضون جزءًا من الليل في الصلاة والدعاء ويصومون نهارها، وآخرون يعدّونها كسائر ليالي شعبان ولا يخصّونها بعبادة معينة.\n\nوالمتفق عليه أن الاستغفار وإصلاح العلاقة مع الناس وصيام التطوع أعمال حسنة في شعبان كله، وهو الباب المؤدي إلى رمضان.","sources":["صحيح البخاري 1969"]},"ramadan-start":{"detail":"رمضان هو الشهر التاسع من السنة الهجرية، وهو الشهر الذي أُنزل فيه القرآن هدى للناس (2:185). وصيامه أحد أركان الإسلام الخمسة (صحيح البخاري 8). وقد فُرض صيامه في المدينة، في السنة الثانية بعد الهجرة.\n\nيبدأ الشهر برؤية الهلال الجديد، فإن تعذّرت رؤيته أُكمل شعبان ثلاثين يومًا (صحيح البخاري 1909). ولهذا قد تختلف بدايته يومًا واحدًا من بلد إلى آخر.\n\nمن الفجر إلى غروب الشمس يمتنع الصائمون عن تناول الطعام والشراب وعن العلاقة الزوجية. ويُعفى المريض والمسافر ويقضيان الأيام فيما بعد، ومن لا يستطيع الصيام أصلًا يطعم مسكينًا بدلًا منه (2:184-185). وقد بيّن القرآن غاية الصيام: تحقيق التقوى (2:183).\n\nوقال النبي محمد ﷺ إنه إذا دخل رمضان فُتحت أبواب السماء وأُغلقت أبواب جهنم وسُلسلت الشياطين (صحيح البخاري 1899). فهو شهر تكثر فيه الصلاة وقراءة القرآن والجود.","sources":["القرآن 2:183-185","صحيح البخاري 8","صحيح البخاري 1909","صحيح البخاري 1899"]},"last-ten-nights":{"detail":"تبدأ العشر الأواخر من رمضان في المساء الذي يسبق اليوم الحادي والعشرين، وتستمر إلى آخر الشهر الذي يكون 29 أو 30 يومًا. وهي أثمن أوقات رمضان، لأن ليلة القدر في إحدى لياليها.\n\nوقد روت عائشة رضي الله عنها أن النبي محمدًا ﷺ كان إذا دخلت هذه العشر شدّ مئزره وأحيا ليله وأيقظ أهله (صحيح البخاري 2024). وكان يجتهد في العبادة في هذه الليالي أكثر مما يجتهد في غيرها (صحيح مسلم 1175).\n\nوكان يعتكف كذلك، أي يلزم المسجد ليتفرغ للعبادة، في العشر الأواخر من رمضان حتى توفي (صحيح البخاري 2026).\n\nوالمستحب فيها: قيام الليل، وقراءة القرآن، والإكثار من الدعاء، والاستغفار، والصدقة. ومن لم يستطع السهر طويلًا فله أن يصلي قليلًا في كل ليلة، حتى لا تفوته الليلة التي هي خير من ألف شهر (97:3). وفي هذه الأيام أيضًا تُجهَّز زكاة الفطر قبل صلاة العيد.","sources":["صحيح البخاري 2024","صحيح مسلم 1175","صحيح البخاري 2026","القرآن 97:3"]},"laylat-al-qadr":{"detail":"ليلة القدر هي الليلة التي أُنزل فيها القرآن. وقد خُصّت بسورة كاملة: فهي خير من ألف شهر، تنزل فيها الملائكة والروح بإذن ربهم، وهي سلام حتى مطلع الفجر (97:1-5). وسمّاها القرآن أيضًا ليلة مباركة (44:3).\n\nوقد أُخفي تاريخها الدقيق. وأمر النبي محمد ﷺ المؤمنين بأن يلتمسوها في الليالي الوتر من العشر الأواخر من رمضان (صحيح البخاري 2017): أي ليلة 21 أو 23 أو 25 أو 27 أو 29. وليلة السابع والعشرين هي الأكثر ذكرًا، ويجتمع فيها كثير من الناس، لكن ذلك ليس مؤكدًا، وللعلماء فيها أقوال مختلفة. والأحكم أن يجتهد المسلم في الليالي العشر كلها.\n\nوقال النبي ﷺ إن من قام ليلة القدر إيمانًا واحتسابًا غُفر له ما تقدم من ذنبه (صحيح البخاري 2014). والأعمال المستحبة فيها هي قيام الليل وتلاوة القرآن والدعاء وطلب العفو من الله.","sources":["القرآن 97:1-5","القرآن 44:3","صحيح البخاري 2017","صحيح البخاري 2014"]},"eid-al-fitr":{"detail":"عيد الفطر يوافق أول يوم من شهر شوال، وبه يُختم شهر رمضان. وقد طلب القرآن من المؤمنين أن يكملوا عدة الأيام وأن يكبّروا الله على ما هداهم (2:185).\n\nوقبل صلاة العيد تُخرَج زكاة الفطر: وهي صدقة يسيرة من الطعام الأساسي، تجب عن كل فرد من أفراد الأسرة، ليشارك الفقراء في فرحة هذا اليوم. وقد أمر النبي محمد ﷺ بأن تُؤدّى قبل خروج الناس إلى الصلاة (صحيح البخاري 1503).\n\nوفي الصباح يكبّر المسلمون ويلبسون أحسن ثيابهم ويجتمعون لصلاة العيد، وتتبعها خطبة (صحيح البخاري 956). وكان النبي ﷺ لا يخرج إلى الصلاة في هذا اليوم حتى يأكل تمرات (صحيح البخاري 953).\n\nولا يجوز صيام يوم العيد (صحيح البخاري 1991). فهو يوم شكر وزيارة للأهل وإحسان إلى الجيران. أما صيام التطوع، كصيام الست من شوال، فيمكن أن يبدأ من اليوم الثاني.","sources":["القرآن 2:185","صحيح البخاري 1503","صحيح البخاري 956","صحيح البخاري 953","صحيح البخاري 1991"]},"six-shawwal":{"detail":"شوال هو الشهر الذي يلي رمضان. وقد قال النبي محمد ﷺ إن من صام رمضان ثم أتبعه ستة أيام من شوال كان كمن صام السنة كلها (صحيح مسلم 1164).\n\nويفسّر العلماء ذلك بقاعدة أن الحسنة بعشر أمثالها (6:160): فشهر رمضان يُحسب بعشرة أشهر، والأيام الستة تُحسب بشهرين، فيكتمل بذلك عام كامل.\n\nوتصحّ في أي ستة أيام من الشهر. ويعرض التطبيق الأيام من 2 إلى 7 على سبيل التيسير فقط: فيجوز صيامها متتابعة أو متفرقة، في أول شوال أو وسطه أو آخره. واليوم الوحيد المستثنى هو اليوم الأول، يوم العيد، الذي لا يجوز صيامه.\n\nوهذا الصيام تطوع وليس فرضًا. ومن بقيت عليه أيام من رمضان فعليه أن يحسب حسابها كذلك: فكثير من العلماء ينصحون بقضائها أولًا، وآخرون يجيزون صيام الست قبلها. وهو طريقة لطيفة للمحافظة على عادات رمضان الحسنة.","sources":["صحيح مسلم 1164","القرآن 6:160"]},"dhul-hijja-nine":{"detail":"ذو الحجة هو الشهر الثاني عشر، وهو شهر الحج. وأيامه العشرة الأولى من أفضل أيام السنة: فقد قال النبي محمد ﷺ إنه ما من عمل صالح أفضل من العمل في هذه الأيام (صحيح البخاري 969). ويرى كثير من المفسرين كذلك أن الليالي العشر التي أقسم الله بها في القرآن (89:2) هي هذه الأيام.\n\nولأن الصيام من أفضل الأعمال، يُستحب صيام الأيام التسعة الأولى بقدر الاستطاعة. واليوم التاسع، يوم عرفة، آكدها. أما اليوم العاشر فهو عيد الأضحى، ولا يجوز صيامه.\n\nومن الأعمال المستحبة أيضًا تكرار التكبير، والإكثار من حمد الله، والصلاة، والصدقة، وقراءة القرآن. وقد ذكر القرآن ذكر اسم الله في أيام معلومات (22:28).\n\nومن أراد أن يضحّي يُطلب منه ألا يأخذ من شعره ولا من أظفاره من أول الشهر حتى تُذبح أضحيته (صحيح مسلم 1977). وفي هذه الأيام يجتمع الحجاج من أنحاء العالم في مكة.","sources":["صحيح البخاري 969","القرآن 89:2","القرآن 22:28","صحيح مسلم 1977"]},"arafat":{"detail":"اليوم التاسع من ذي الحجة هو يوم عرفة، وهو قلب الحج. من الظهر إلى غروب الشمس يقف الحجاج في صعيد عرفات، قرب مكة، مصلّين داعين. والوقوف بعرفة هو الركن الأعظم في الحج.\n\nوفي هذا اليوم، وكان يوم جمعة، في حجة الوداع التي حجّها النبي محمد ﷺ، نزلت الآية التي تعلن أن الله أكمل الدين (5:3)، كما روى عمر بن الخطاب (صحيح البخاري 45).\n\nوقال النبي ﷺ إنه ما من يوم يُعتق الله فيه من النار عبادًا أكثر من يوم عرفة (صحيح مسلم 1348).\n\nولغير الحاج يُستحب صيام هذا اليوم استحبابًا مؤكدًا: فقد قال النبي ﷺ إنه يكفّر ذنوب السنة الماضية والسنة القادمة (صحيح مسلم 1162). أما الحجاج فلا يُطلب منهم الصيام، ولم يكن النبي ﷺ صائمًا وهو واقف بعرفة (صحيح البخاري 1988).\n\nفهو يوم دعاء وذكر لله واستغفار، أينما كان المسلم.","sources":["القرآن 5:3","صحيح البخاري 45","صحيح مسلم 1348","صحيح مسلم 1162","صحيح البخاري 1988"]},"eid-al-adha":{"detail":"عيد الأضحى يوافق اليوم العاشر من ذي الحجة، وهو اليوم الذي يلي عرفة. ويتزامن هذا العيد مع أهم مناسك الحج في منى ومكة.\n\nوهو يذكّر بالابتلاء الذي مرّ به إبراهيم عليه السلام. فقد رأى في المنام أنه يذبح ابنه، فاستسلم الاثنان لأمر الله، وفدى الله الابن بذبح عظيم (37:102-107).\n\nيبدأ هذا اليوم بصلاة العيد، وتتبعها خطبة (صحيح البخاري 956). وبعد الصلاة يذبح القادرون شاة من الضأن أو المعز أو بقرة أو بعيرًا. ويأكل أهل البيت من اللحم، ويُهدى منه إلى الأقارب والجيران، ويُعطى منه الفقراء. ويذكّر القرآن المؤمنين بأن الله لا يناله اللحم ولا الدم، وإنما تناله تقواهم (22:37).\n\nولا يجوز صيام هذا اليوم (صحيح البخاري 1991). ويكبّر المسلمون ويلبسون أحسن ثيابهم ويتزاورون ويتقاسمون الطعام. ويجوز كذلك أن تُذبح الأضحية في الأيام التي تليه.","sources":["القرآن 37:102-107","صحيح البخاري 956","القرآن 22:37","صحيح البخاري 1991"]},"tashriq":{"detail":"أيام التشريق هي الحادي عشر والثاني عشر والثالث عشر من ذي الحجة، وهي الأيام الثلاثة التي تلي عيد الأضحى. وقد وصفها النبي محمد ﷺ بأنها أيام أكل وشرب وذكر لله (صحيح مسلم 1141).\n\nوفي هذه الأيام يقيم الحجاج في منى ويرمون كل يوم بالحصى الجمرات الثلاث. وقد أمرهم القرآن بذكر الله في هذه الأيام المعدودات، وبيّن أنه لا إثم على من تعجّل فرحل بعد يومين، ولا على من تأخّر (2:203). فللحجاج أن يرحلوا في اليوم الثاني عشر أو أن يبقوا إلى الثالث عشر.\n\nولا يجوز صيام هذه الأيام. والاستثناء الوحيد المرويّ هو للحاج الذي وجب عليه الهدي ولم يجده (صحيح البخاري 1997).\n\nأما سائر الناس فهي لهم أيام فرح وشكر: يتقاسمون لحم الأضاحي، ويزورون الأقارب، ويكبّرون، وخاصة بعد الصلوات اليومية. ويجوز ذبح الأضحية في هذه الأيام كذلك، على تفصيل يختلف بين المذاهب الفقهية.","sources":["صحيح مسلم 1141","القرآن 2:203","صحيح البخاري 1997"]}}$tk$::jsonb)
  on conflict (kind, lang) do update set payload = excluded.payload, updated_at = now();
